// Anti-corruption layer: raw API DTOs → stable app models, so screens never
// depend on backend shape. Screens read the camelCase domain name; the raw
// backend name appears exactly once, in the mapper below it.
export type Dto = Record<string, any>;

// unknown in, not Dto[]: since responses are parsed through their zod
// schema the hooks hand back an unknown, and the runtime guard below is what
// makes that safe — a narrower parameter type would only force every call
// site to cast past the same check.
export function mapItem<M>(dto: unknown, map: (d: Dto) => M): M | null {
  return dto !== null && typeof dto === 'object' ? map(dto as Dto) : null;
}

// A LIST RESPONSE ARRIVES IN ONE OF THREE SHAPES, and the screen must not
// care which. The Beacon reference app states this outright — its
// accountListSchema is `z.union([z.array(account), z.object({records:…})])`
// — and the gateway really does send both: `/card` answers with a bare
// array, the paged account endpoints wrap in `records`, and some services
// put the page under `data`.
//
// Returning [] for an unrecognised shape is what made this worth spelling
// out: a wrapped response rendered an EMPTY list with no error and no log
// line, which on device is indistinguishable from "the customer has no
// accounts". The binding's arrayPath is still honoured first; this only
// decides what to do when the value it points at is not itself an array.
/**
 * The rows of a list response, whatever envelope the gateway used.
 *
 * A binding records the array path its designer saw, but the envelope is the
 * GATEWAY's choice and varies by service: Beacon's account, card and
 * transaction endpoints all answer `{records,count}` while the binding says
 * "data". Reading the declared path alone produced `undefined`, so the list
 * mapped nothing and rendered empty — and because a list's empty-state is
 * suppressed once the query succeeds, the Figma sample rows standing in
 * before the call VANISHED the moment the 200 landed. That is the "it looked
 * fine, then it broke on load" report from the Accounts home.
 *
 * Declared path first, so anything already resolving keeps resolving; then
 * the usual envelope keys; then the body itself when it is the array. Same
 * shapes the Beacon reference app accepts in its own list schemas.
 */
export function listRows(body: unknown, arrayPath: string): unknown[] {
  const at = (src: unknown, path: string): unknown => {
    if (!path) return src;
    let cur = src;
    for (const seg of path.split('.')) {
      if (cur === null || typeof cur !== 'object') return undefined;
      cur = (cur as Record<string, unknown>)[seg];
    }
    return cur;
  };
  const declared = at(body, arrayPath);
  if (Array.isArray(declared)) return declared;
  if (Array.isArray(body)) return body;
  if (body !== null && typeof body === 'object') {
    for (const key of ['records', 'data', 'items', 'content', 'results']) {
      const v = (body as Record<string, unknown>)[key];
      if (Array.isArray(v)) return v;
    }
  }
  return [];
}

/** The rows of a list response: the array itself, or the first array under
 * one of the usual envelope keys. */
function dtoRows(dtos: unknown): Dto[] {
  if (Array.isArray(dtos)) return dtos as Dto[];
  if (dtos === null || typeof dtos !== 'object') return [];
  const o = dtos as Record<string, unknown>;
  for (const key of ['records', 'data', 'items', 'content']) {
    const v = o[key];
    if (Array.isArray(v)) return v as Dto[];
  }
  return [];
}

export function mapList<M>(dtos: unknown, map: (d: Dto) => M): M[] {
  return dtoRows(dtos).map(map);
}

